CustomField.formula:
IF( OR( ISBLANK(CheckIn_Date__c), ISBLANK(CheckOut_Date__c) ), NULL,
/* Total minutes (never below 0) */ IF( MAX(0, FLOOR((CheckOut_Date__c - CheckIn_Date__c) * 1440)) < 60,
/* Minutes only → 00m / 05m / 18m */ IF( MAX(0, FLOOR((CheckOut_Date__c - CheckIn_Date__c) * 1440)) < 10, "0" & TEXT(MAX(0, FLOOR((CheckOut_Date__c - CheckIn_Date__c) * 1440))) & "m", TEXT(MAX(0, FLOOR((CheckOut_Date__c - CheckIn_Date__c) * 1440))) & "m" ),
/* Hours + Minutes */ IF( FLOOR(MAX(0, FLOOR((CheckOut_Date__c - CheckIn_Date__c) * 1440)) / 60) < 10, "0" & TEXT(FLOOR(MAX(0, FLOOR((CheckOut_Date__c - CheckIn_Date__c) * 1440)) / 60)), TEXT(FLOOR(MAX(0, FLOOR((CheckOut_Date__c - CheckIn_Date__c) * 1440)) / 60)) ) & "h " &
IF( MOD(MAX(0, FLOOR((CheckOut_Date__c - CheckIn_Date__c) * 1440)), 60) < 10, "0" & TEXT(MOD(MAX(0, FLOOR((CheckOut_Date__c - CheckIn_Date__c) * 1440)), 60)), TEXT(MOD(MAX(0, FLOOR((CheckOut_Date__c - CheckIn_Date__c) * 1440)), 60)) ) & "m" ) )
